427	    if (!isInt(o.resourceSeq)) bad('resourceSeq 必须是非负整数');
428	    store.resourceSeq = o.resourceSeq;
429	  }
430	  if (o.bookingSeq !== undefined) {
431	    if (!isInt(o.bookingSeq)) bad('bookingSeq 必须是非负整数');
432	    store.bookingSeq = o.bookingSeq;
433	  }
434	  if (o.seriesSeq !== undefined) {
435	    if (!isInt(o.seriesSeq)) bad('seriesSeq 必须是非负整数');
436	    store.seriesSeq = o.seriesSeq;
437	  }
438	  if (o.waitlistSeq !== undefined) {
439	    if (!isInt(o.waitlistSeq)) bad('waitlistSeq 必须是非负整数');
