451	  if (o.resources !== undefined && !Array.isArray(o.resources)) bad('resources 必须是数组');
452	  if (o.bookings !== undefined && !Array.isArray(o.bookings)) bad('bookings 必须是数组');
453	  if (o.series !== undefined && !Array.isArray(o.series)) bad('series 必须是数组');
454	  if (o.waitlist !== undefined && !Array.isArray(o.waitlist)) bad('waitlist 必须是数组');
