506	  });
507	
508	  const bookingIds = new Set<string>();
509	  rawBookings.forEach((item, idx) => {
510	    const at = `bookings[${idx}]`;
511	    if (typeof item !== 'object' || item === null || Array.isArray(item)) bad(`${at} 必须是对象`);
