513	    if (typeof b.id !== 'string' || !/^B\d{4,}$/.test(b.id)) bad(`${at}.id 非法: ${String(b.id)}`);
514	    if (bookingIds.has(b.id)) bad(`预约标识重复: ${b.id}`);
