524	      }
525	      if (seen.has(rid)) bad(`${at}(${b.id}) 资源重复: ${rid}`);
526	      seen.add(rid);
527	    });
528	    if (typeof b.start !== 'string' || typeof b.end !== 'string') {
529	      bad(`${at}(${b.id}) 起止时间必须是字符串`);
530	    }
531	    const s = parseDateTime(b.start, `${at}(${b.id}).start`);
532	    const e = parseDateTime(b.end, `${at}(${b.id}).end`);
533	    if (e <= s) bad(`${at}(${b.id}) 结束必须晚于开始`);
534	    if (b.status !== 'active' && b.status !== 'cancelled') {
535	      bad(`${at}(${b.id}).status 非法: ${String(b.status)}`);
536	    }
537	    let seriesId: string | undefined;
538	    if (b.seriesId !== undefined) {
539	      if (typeof b.seriesId !== 'string' || !/^S\d{4,}$/.test(b.seriesId)) {
540	        bad(`${at}(${b.id}).seriesId 非法: ${String(b.seriesId)}`);
541	      }
542	      if (!seriesIds.has(b.seriesId)) bad(`${at}(${b.id}) 引用了未知系列: ${b.seriesId}`);
543	      seriesId = b.seriesId;
