766	      if (!Array.isArray(side.resourceIds) || side.resourceIds.length === 0) {
767	        bad(`${sat}.resourceIds 必须是非空数组`);
768	      }
769	      const ids = side.resourceIds as unknown[];
770	      const seen = new Set<string>();
771	      ids.forEach((rid) => {
772	        if (typeof rid !== 'string' || !resourceIds.has(rid)) {
773	          bad(`${sat} 引用了未知资源: ${String(rid)}`);
774	        }
775	        if (seen.has(rid as string)) bad(`${sat} 资源重复: ${rid}`);
776	        seen.add(rid as string);
777	      });
778	      return {start: side.start as string, end: side.end as string, resourceIds: [...seen].sort()};
779	    };
780	
781	    const opItems: BatchOpItem[] = [];
782	    itemRecs.forEach((itRaw, j) => {
783	      const iat = `${at}(${op.id}).items[${j}]`;
784	      if (typeof itRaw !== 'object' || itRaw === null || Array.isArray(itRaw)) {
785	        bad(`${iat} 必须是对象`);
786	      }
787	      const it = itRaw as Record<string, unknown>;
788	      for (const k of Object.keys(it)) {
789	        if (k !== 'bookingId' && k !== 'seriesId' && k !== 'before' && k !== 'after') {
790	          bad(`${iat} 存在未知字段 “${k}”（只允许 bookingId、seriesId、before、after）`);
791	        }
792	      }
793	      if (typeof it.bookingId !== 'string' || !/^B\d{4,}$/.test(it.bookingId)) {
794	        bad(`${iat}.bookingId 非法: ${String(it.bookingId)}`);
795	      }
796	      if (itemBookingIds.has(it.bookingId as string)) {
797	        bad(`${iat} 预约标识在同一操作内重复: ${it.bookingId}`);
798	      }
799	      itemBookingIds.add(it.bookingId as string);
800	      // 预约记录从不物理删除（取消也保留），引用必须可解析
801	      if (!bookingById.has(it.bookingId as string)) {
802	        bad(`${iat} 引用了未知预约: ${it.bookingId}`);
803	      }
804	      let seriesId: string | undefined;
805	      if (it.seriesId !== undefined) {
806	        if (typeof it.seriesId !== 'string' || !/^S\d{4,}$/.test(it.seriesId)) {
807	          bad(`${iat}.seriesId 非法: ${String(it.seriesId)}`);
808	        }
809	        if (!seriesIds.has(it.seriesId)) bad(`${iat} 引用了未知系列: ${it.seriesId}`);
810	        seriesId = it.seriesId;
811	      }
812	      if (it.before === undefined) bad(`${iat} 缺少改期前快照 before`);
813	      if (it.after === undefined) bad(`${iat} 缺少改期后快照 after`);
814	      const before = validateSide(it.before, 'before');
815	      const after = validateSide(it.after, 'after');
816	      const rec: BatchOpItem = {
817	        bookingId: it.bookingId as string,
818	        before,
819	        after,
820	      };
821	      if (seriesId !== undefined) rec.seriesId = seriesId;
822	      opItems.push(rec);
823	    });
824	
825	    store.batchOps.push({
826	      id: op.id,
827	      status: op.status as BatchOpStatus,
828	      items: opItems,
829	    });
830	  });
831	  if (store.batchSeq !== 0 && store.batchOps.length === 0) {
832	    bad('batchSeq 非零却没有任何批量改期操作记录（计数与记录不一致）');
833	  }
834	  // 操作记录从不删除（撤销也保留），标识序号集合必须恰好为 1..batchSeq
835	  for (let i = 1; i <= store.batchSeq; i++) {
836	    if (!batchOpNums.has(i)) bad(`批量改期操作记录缺号：找不到标识序号 ${i} 的记录`);
837	  }
838	
839	  // iCalendar 导入身份记录：UID 唯一且非空。两类身份：
840	  //   独立事件 -> bookingId 指向一项普通预约；
841	  //   按周重复事件 -> seriesId 指向一个系列，occurrences 按原发生顺序记录每个
842	  //   未排除发生的原开始时间与对应成员（count/exdates 为首次请求的重复参数）。
843	  // 成员预约与系列均不得被另一条导入记录重复关联；快照自身须合法（真实时间、
844	  // 结束晚于开始、资源已知且不重复、COUNT 合法、排除集合与发生映射自洽）。
845	  // 成员现状（被改期/取消）与首次请求不同不算损坏。
846	  const importUids = new Set<string>();
847	  const importLinkedBookings = new Set<string>();
848	  const importLinkedSeries = new Set<string>();
849	  const claimBooking = (uid: string, bId: string, at: string): void => {
850	    if (!bookingById.has(bId)) bad(`${at}(UID “${uid}”) 关联了未知预约: ${bId}`);
851	    if (importLinkedBookings.has(bId)) {
852	      bad(`${at}(UID “${uid}”) 预约 ${bId} 已被另一条导入记录关联（一项预约只能对应一个 UID）`);
853	    }
854	    importLinkedBookings.add(bId);
855	  };
856	  rawImports.forEach((item, idx) => {
857	    const at = `imports[${idx}]`;
858	    if (typeof item !== 'object' || item === null || Array.isArray(item)) bad(`${at} 必须是对象`);
859	    const im = item as Record<string, unknown>;
860	    if (typeof im.uid !== 'string' || im.uid === '') bad(`${at}.uid 必须是非空字符串`);
861	    if (importUids.has(im.uid)) bad(`导入记录 UID 重复: ${im.uid}`);
862	    importUids.add(im.uid);
863	    const uid = im.uid;
864	
865	    const hasBooking = im.bookingId !== undefined;
866	    const hasSeries = im.seriesId !== undefined;
867	    if (hasBooking === hasSeries) {
868	      bad(`${at}(UID “${uid}”) 必须恰好提供 bookingId（独立事件）或 seriesId（重复事件）之一`);
869	    }
870	    if (typeof im.start !== 'string' || typeof im.end !== 'string') {
871	      bad(`${at}(UID “${uid}”) 快照起止时间必须是字符串`);
872	    }
873	    const s = parseDateTime(im.start as string, `${at}(UID “${uid}”).start`);
874	    const e = parseDateTime(im.end as string, `${at}(UID “${uid}”).end`);
875	    if (e <= s) bad(`${at}(UID “${uid}”) 快照结束必须晚于开始`);
876	    if (!Array.isArray(im.resourceIds) || im.resourceIds.length === 0) {
877	      bad(`${at}(UID “${uid}”).resourceIds 必须是非空数组`);
878	    }
879	    const rids = im.resourceIds as unknown[];
880	    const rseen = new Set<string>();
881	    rids.forEach((rid) => {
882	      if (typeof rid !== 'string' || !resourceIds.has(rid)) {
883	        bad(`${at}(UID “${uid}”) 快照引用了未知资源: ${String(rid)}`);
884	      }
885	      if (rseen.has(rid)) bad(`${at}(UID “${uid}”) 快照资源重复: ${rid}`);
886	      rseen.add(rid);
887	    });
888	
889	    const rec: ImportRec = {
890	      uid,
891	      start: im.start as string,
892	      end: im.end as string,
893	      resourceIds: [...rseen].sort(),
894	    };
895	
896	    if (hasBooking) {
897	      // 独立事件身份：不得携带重复字段
898	      if (typeof im.bookingId !== 'string' || !/^B\d{4,}$/.test(im.bookingId)) {
899	        bad(`${at}(UID “${uid}”).bookingId 非法: ${String(im.bookingId)}`);
900	      }
901	      for (const k of ['count', 'exdates', 'occurrences', 'exceptions']) {
902	        if (im[k] !== undefined) bad(`${at}(UID “${uid}”) 独立事件身份不应携带 ${k}`);
903	      }
904	      claimBooking(uid, im.bookingId as string, at);
905	      rec.bookingId = im.bookingId as string;
906	      store.imports.push(rec);
907	      return;
908	    }
909	
910	    // 重复事件身份
911	    if (typeof im.seriesId !== 'string' || !/^S\d{4,}$/.test(im.seriesId)) {
912	      bad(`${at}(UID “${uid}”).seriesId 非法: ${String(im.seriesId)}`);
913	    }
914	    if (!seriesIds.has(im.seriesId)) {
915	      bad(`${at}(UID “${uid}”) 关联了未知系列: ${im.seriesId}`);
916	    }
917	    if (importLinkedSeries.has(im.seriesId)) {
918	      bad(`${at}(UID “${uid}”) 系列 ${im.seriesId} 已被另一条导入记录关联（一个系列只能对应一个 UID）`);
919	    }
920	    importLinkedSeries.add(im.seriesId);
921	    rec.seriesId = im.seriesId;
922	
923	    if (!isInt(im.count) || im.count < 1 || im.count > MAX_OCCURRENCES) {
924	      bad(`${at}(UID “${uid}”).count 必须是 1..${MAX_OCCURRENCES} 的整数`);
925	    }
926	    rec.count = im.count;
927	    if (!Array.isArray(im.exdates)) bad(`${at}(UID “${uid}”).exdates 必须是数组`);
928	    const exSet = new Set<string>();
929	    (im.exdates as unknown[]).forEach((xv, j) => {
930	      if (typeof xv !== 'string') bad(`${at}(UID “${uid}”).exdates[${j}] 必须是时间字符串`);
931	      parseDateTime(xv, `${at}(UID “${uid}”).exdates[${j}]`);
932	      if (exSet.has(xv)) bad(`${at}(UID “${uid}”) 排除时间重复: ${xv}`);
933	      exSet.add(xv);
934	    });
935	    rec.exdates = [...exSet].sort();
936	
937	    if (!Array.isArray(im.occurrences) || im.occurrences.length === 0) {
938	      bad(`${at}(UID “${uid}”).occurrences 必须是非空数组（全部发生被排除的首次请求非法）`);
939	    }
940	    const occTimes = new Set<string>();
941	    const occs: Array<{start: string; bookingId: string}> = [];
942	    (im.occurrences as unknown[]).forEach((ov, j) => {
943	      const oat = `${at}(UID “${uid}”).occurrences[${j}]`;
944	      if (typeof ov !== 'object' || ov === null || Array.isArray(ov)) bad(`${oat} 必须是对象`);
945	      const o = ov as Record<string, unknown>;
946	      for (const k of Object.keys(o)) {
947	        if (k !== 'start' && k !== 'bookingId') bad(`${oat} 存在未知字段 “${k}”`);
948	      }
949	      if (typeof o.start !== 'string') bad(`${oat}.start 必须是时间字符串`);
950	      parseDateTime(o.start, `${oat}.start`);
951	      if (occTimes.has(o.start)) bad(`${at}(UID “${uid}”) 原发生时间重复: ${o.start}`);
952	      occTimes.add(o.start);
953	      if (typeof o.bookingId !== 'string' || !/^B\d{4,}$/.test(o.bookingId)) {
954	        bad(`${oat}.bookingId 非法: ${String(o.bookingId)}`);
955	      }
956	      claimBooking(uid, o.bookingId, at);
957	      occs.push({start: o.start, bookingId: o.bookingId});
958	    });
959	
960	    // 映射自洽性：按首项与 COUNT 展开全部原发生（须在四位年份内），
961	    // 未排除发生必须恰好等于 occurrences（时间集合一致、顺序按发生先后）
962	    const expectedAll: string[] = [];
963	    for (let i = 0; i < rec.count; i++) {
964	      const raw = formatDateTime(s + i * 7 * 1440);
965	      if (raw === null) bad(`${at}(UID “${uid}”) 重复展开超出四位年份范围（0001-9999）`);
966	      expectedAll.push(raw);
967	    }
968	    const expectedKept = expectedAll.filter((t) => !exSet.has(t));
969	    const excludedNotInSeries = [...exSet].filter((t) => !expectedAll.includes(t));
970	    if (excludedNotInSeries.length > 0) {
971	      bad(`${at}(UID “${uid}”) 排除时间不匹配任何原发生: ${excludedNotInSeries.join('、')}`);
972	    }
973	    if (occs.length !== expectedKept.length || occs.some((o, j) => o.start !== expectedKept[j])) {
974	      bad(
975	        `${at}(UID “${uid}”) 发生映射缺漏或重复：COUNT=${rec.count}、排除 ${exSet.size} 项` +
976	          `时应有 ${expectedKept.length} 个未排除发生且按发生顺序排列`,
977	      );
978	    }
979	    // 成员必须恰好为所关联系列的全部成员（1:1：系列成员不重不漏）
980	    const seriesMembers = new Set(
981	      store.bookings.filter((b) => b.seriesId === rec.seriesId).map((b) => b.id),
982	    );
983	    for (const o of occs) {
984	      if (!seriesMembers.has(o.bookingId)) {
985	        bad(`${at}(UID “${uid}”) 成员 ${o.bookingId} 不属于系列 ${rec.seriesId}`);
986	      }
987	    }
988	    if (occs.length !== seriesMembers.size) {
989	      bad(`${at}(UID “${uid}”) 系列 ${rec.seriesId} 存在未登记在 occurrences 中的成员（系列与发生映射必须一一对应）`);
990	    }
991	    rec.occurrences = occs;
992	
993	    // 例外集合（旧记录无 exceptions 字段视为空集合）：每项按原发生时间
994	    // （RECURRENCE-ID，必须命中某个未排除原发生）关联改期后起止，同一原发生
995	    // 至多一个例外；快照自身须合法（真实时间、结束晚于开始）。成员现状与
996	    // 例外快照不同不算损坏（本地可再改期、取消）。
997	    const exceptions: Array<{recurrenceId: string; start: string; end: string}> = [];
998	    if (im.exceptions !== undefined) {
999	      if (!Array.isArray(im.exceptions)) bad(`${at}(UID “${uid}”).exceptions 必须是数组`);
1000	      const keptTimes = new Set(occs.map((o) => o.start));
1001	      const exOccSeen = new Set<string>();
1002	      (im.exceptions as unknown[]).forEach((xv, j) => {
1003	        const eat = `${at}(UID “${uid}”).exceptions[${j}]`;
1004	        if (typeof xv !== 'object' || xv === null || Array.isArray(xv)) bad(`${eat} 必须是对象`);
1005	        const x = xv as Record<string, unknown>;
1006	        for (const k of Object.keys(x)) {
1007	          if (k !== 'recurrenceId' && k !== 'start' && k !== 'end') bad(`${eat} 存在未知字段 “${k}”`);
1008	        }
1009	        if (typeof x.recurrenceId !== 'string') bad(`${eat}.recurrenceId 必须是时间字符串`);
1010	        parseDateTime(x.recurrenceId, `${eat}.recurrenceId`);
1011	        if (!keptTimes.has(x.recurrenceId)) {
1012	          bad(`${at}(UID “${uid}”) 例外的 RECURRENCE-ID ${x.recurrenceId} 不匹配任何未排除原发生`);
1013	        }
1014	        if (exOccSeen.has(x.recurrenceId)) {
1015	          bad(`${at}(UID “${uid}”) 同一原发生存在重复例外: ${x.recurrenceId}`);
1016	        }
1017	        exOccSeen.add(x.recurrenceId);
1018	        if (typeof x.start !== 'string') bad(`${eat}.start 必须是时间字符串`);
1019	        if (typeof x.end !== 'string') bad(`${eat}.end 必须是时间字符串`);
1020	        const xs = parseDateTime(x.start, `${eat}.start`);
1021	        const xe = parseDateTime(x.end, `${eat}.end`);
1022	        if (xe <= xs) bad(`${eat} 结束必须晚于开始`);
1023	        exceptions.push({recurrenceId: x.recurrenceId, start: x.start, end: x.end});
1024	      });
1025	    }
1026	    // 规范化为按原发生顺序排列，顺序不影响身份
1027	    const occOrder = new Map(occs.map((o, k) => [o.start, k]));
1028	    exceptions.sort((a, b) => occOrder.get(a.recurrenceId)! - occOrder.get(b.recurrenceId)!);
1029	    rec.exceptions = exceptions;
1030	
1031	    store.imports.push(rec);
1032	  });
1033	
1034	  store.resources.sort((a, b) => a.id.localeCompare(b.id));
1035	  store.bookings.sort((a, b) => a.id.localeCompare(b.id));
1036	  store.series.sort((a, b) => a.id.localeCompare(b.id));
1037	  store.waitlist.sort((a, b) => a.seq - b.seq || a.id.localeCompare(b.id));
1038	  store.closures.sort((a, b) => a.id.localeCompare(b.id));
1039	  store.batchOps.sort((a, b) => Number(a.id.slice(1)) - Number(b.id.slice(1)));
1040	  store.imports.sort((a, b) => a.uid.localeCompare(b.uid));
1041	  return store;
1042	}
1043	
1044	async function loadStore(file: string): Promise<Store> {
1045	  let text: string;
1046	  try {
1047	    text = await readFile(file, 'utf8');
1048	  } catch (err) {
1049	    if ((err as NodeJS.ErrnoException).code === 'ENOENT') return emptyStore();
1050	    throw new BizError(`无法读取数据文件 ${file}: ${(err as Error).message}`);
1051	  }
1052	  let raw: unknown;
1053	  try {
1054	    raw = JSON.parse(text);
1055	  } catch (err) {
1056	    throw new BizError(
1057	      `数据文件 ${file} 已损坏，不是合法 JSON：${(err as Error).message}（原文件已保留，未当作空数据覆盖）`,
1058	    );
1059	  }
1060	  return validateStore(raw, file);
1061	}
1062	
1063	// 先完整写入临时文件，再原子改名；任何失败都不触碰原文件
1064	async function saveStore(file: string, store: Store): Promise<void> {
1065	  let json: string;
1066	  try {
1067	    json = JSON.stringify(store, null, 2) + '\n';
1068	  } catch (err) {
1069	    throw new BizError(`序列化数据失败：${(err as Error).message}（原文件已保留）`);
1070	  }
1071	  const tmp = `${file}.${process.pid}.tmp`;
1072	  try {
1073	    await writeFile(tmp, json, {encoding: 'utf8', flag: 'wx'});
1074	    await rename(tmp, file);
1075	  } catch (err) {
1076	    await unlink(tmp).catch(() => {});
1077	    throw new BizError(`保存数据文件 ${file} 失败：${(err as Error).message}（原文件已保留）`);
1078	  }
1079	}
1080	
1081	// ---------------------------------------------------------------------------
1082	// 多进程写入保护（同一数据文件全局互斥）
1083	//
1084	// 所有修改入口在读取数据前先取得本数据文件的写入保护（锁文件，wx 独占创建），
1085	// 保护覆盖读取决策所需状态、业务校验、标识分配与原子保存全过程，命令结束时
1086	// 统一释放（正常结束、校验失败、保存失败均释放）。锁文件按数据文件的规范路径
1087	// 命名：相对路径、绝对路径与含 ./.. 的等价写法共享同一把锁；不同数据文件
1088	// 互不影响；数据文件尚不存在时同样受保护。竞争可等待，但 5 秒内未取得即以
1089	// 退出码 1 报告占用（可重试）。进程异常退出会留下残留锁：recover-lock 仅在
1090	// 确认原写入进程已退出后解除，存活或无法确认一律拒绝，不按保护存在时长抢占。
1091	//
1092	// 交接互斥：取得（wx 独占创建）、释放（仅删自己取得的那份）、恢复三者都不得
1093	// 误删他人的保护。恢复入口之间以恢复协调文件（<锁文件>.recover，wx 独占创建）
1094	// 互斥：任一时刻至多一个恢复者持有协调文件，持有者在互斥内重新核对目标后才
1095	// 删除锁文件——持有协调文件期间，原持有者已确认退出（不会再释放）、其他恢复者
1096	// 进不了互斥、新写入者只能在锁文件不存在时取得（wx），因此互斥内的删除恰好
1097	// 删除本次确认的那一份残留保护，绝不误删新写入者已取得的保护；发现目标更替
1098	// （锁已易主或已消失）则以退出码 1 说明原因或按无操作退出 0，不宣称解除新保护。
1099	// 恢复者异常退出会留下残留协调文件：下一恢复入口在确认其持有者已退出后清理
1100	// 并重试，无需人工删文件。
1101	// ---------------------------------------------------------------------------
1102	
1103	const LOCK_TIMEOUT_MS = 5000; // 取得写入保护的最长等待时间
1104	const LOCK_RETRY_MS = 40; // 竞争重试间隔（含随机抖动，避免齐步）
1105	
1106	// 数据文件的规范路径：解析相对路径与 ./..，并尽量解析符号链接
1107	// （文件尚不存在时解析其父目录，父目录也不可用时退化为绝对路径）
1108	function canonicalDataPath(file: string): string {
1109	  const abs = resolve(file);
1110	  try {
1111	    return realpathSync(abs);
1112	  } catch {
1113	    try {
1114	      return join(realpathSync(dirname(abs)), basename(abs));
1115	    } catch {
1116	      return abs;
1117	    }
1118	  }
1119	}

