1450	// 从连续区间中扣除一段停用（左闭右开），返回剩余连续区间
1451	function subtractSegments(
1452	  segments: Array<[number, number]>,
1453	  cuts: Array<[number, number]>,
1454	): Array<[number, number]> {
1455	  let result = segments;
1456	  for (const [cs, ce] of mergeIntervals(cuts)) {
1457	    const next: Array<[number, number]> = [];
1458	    for (const [s, e] of result) {
1459	      if (ce <= s || e <= cs) {
1460	        next.push([s, e]);
1461	        continue;
1462	      }
1463	      if (s < cs) next.push([s, cs]);
1464	      if (ce < e) next.push([ce, e]);
1465	    }
1466	    result = next;
1467	  }
1468	  return result;
1469	}
