1591	
1592	interface ValidationTarget {
1593	  startMin: number;
1594	  endMin: number;
1595	  resourceIds: string[]; // 已校验、按标识排序的完整目标资源集合
1596	}
1597	
1598	interface BatchTargetFailure {
1599	  index: number; // 目标数组下标（0 基）；报告顺序与业务定位由入口决定
1600	  gaps: CoverageGap[]; // 实际可用时间不能完整覆盖目标的资源及相关有效停用
1601	  external: Conflict[]; // 与批外有效预约的冲突（按预约标识排序）
1602	  internal: Array<{otherIndex: number; shared: string[]}>; // 批内冲突（双方互见）
1603	}
1604	
1605	// excludeBookingIds：本批涉及预约的标识，其当前占用不计入批外占用
1606	// （改期与撤销据此允许整批交换时段和资源；系列与导入传空集合）
1607	function validateBatchTargets(
1608	  store: Store,
1609	  targets: ReadonlyArray<ValidationTarget>,
1610	  excludeBookingIds: ReadonlySet<string> = new Set<string>(),
1611	): BatchTargetFailure[] {
1612	  const failures: BatchTargetFailure[] = [];
1613	  for (let i = 0; i < targets.length; i++) {
1614	    const t = targets[i];
1615	    const gaps = findCoverageGaps(store, t.resourceIds, t.startMin, t.endMin);
1616	    const external = findConflicts(store, t.resourceIds, t.startMin, t.endMin).filter(
1617	      (c) => !excludeBookingIds.has(c.booking.id),
1618	    );
1619	    const wanted = new Set(t.resourceIds);
1620	    const internal: BatchTargetFailure['internal'] = [];
1621	    for (let j = 0; j < targets.length; j++) {
1622	      if (j === i) continue;
1623	      const o = targets[j];
1624	      if (!(o.startMin < t.endMin && t.startMin < o.endMin)) continue;
1625	      const shared = o.resourceIds.filter((id) => wanted.has(id)).sort();
1626	      if (shared.length > 0) internal.push({otherIndex: j, shared});
1627	    }
1628	    if (gaps.length > 0 || external.length > 0 || internal.length > 0) {
1629	      failures.push({index: i, gaps, external, internal});
1630	    }
1631	  }
1632	  return failures;
1633	}
