1645	function splitGlobalArgs(argv: string[]): GlobalArgs {
1646	  const result: GlobalArgs = {dataFile: DEFAULT_DATA_FILE, help: false, rest: []};
1647	  for (let i = 0; i < argv.length; i++) {
1648	    const a = argv[i];
1649	    if (a === '-h' || a === '--help') {
1650	      result.help = true;
1651	    } else if (a === '--data') {
1652	      const v = argv[++i];
1653	      if (v === undefined) throw new UsageError('选项 --data 缺少数据文件路径');
1654	      result.dataFile = v;
1655	    } else if (a.startsWith('--data=')) {
1656	      result.dataFile = a.slice('--data='.length);
1657	      if (result.dataFile === '') throw new UsageError('选项 --data 缺少数据文件路径');
1658	    } else {
1659	      result.rest.push(a);
1660	    }
1661	  }
1662	  return result;
1663	}
