1670	// 子命令选项解析：allowed 中列出的选项均需带值；multi 中的选项可重复
1671	function parseFlags(args: string[], allowed: string[], multi: string[] = []): ParsedFlags {
1672	  const allowedSet = new Set(allowed);
1673	  const multiSet = new Set(multi);
1674	  const values = new Map<string, string[]>();
1675	  const positionals: string[] = [];
1676	
1677	  const takeValue = (key: string, inline: string | undefined, index: number): [string, number] => {
1678	    if (inline !== undefined) return [inline, index];
1679	    const v = args[index + 1];
1680	    if (v === undefined || v.startsWith('-')) {
1681	      throw new UsageError(`选项 --${key} 缺少值`);
1682	    }
1683	    return [v, index + 1];
1684	  };
1685	
1686	  for (let i = 0; i < args.length; i++) {
1687	    const a = args[i];
1688	    if (a.startsWith('--')) {
1689	      let key: string;
1690	      let inline: string | undefined;
1691	      const eq = a.indexOf('=');
1692	      if (eq >= 0) {
1693	        key = a.slice(2, eq);
1694	        inline = a.slice(eq + 1);
1695	      } else {
1696	        key = a.slice(2);
1697	      }
1698	      if (!allowedSet.has(key)) throw new UsageError(`未知选项: --${key}`);
1699	      let v: string;
1700	      [v, i] = takeValue(key, inline, i);
1701	      if (v === '') throw new UsageError(`选项 --${key} 的值不能为空`);
1702	      if (!multiSet.has(key) && values.has(key)) {
1703	        throw new UsageError(`选项 --${key} 只能指定一次`);
1704	      }
1705	      const list = values.get(key) ?? [];
1706	      list.push(v);
1707	      values.set(key, list);
1708	    } else if (a.startsWith('-') && a !== '-') {
1709	      throw new UsageError(`未知参数: ${a}`);
1710	    } else {
1711	      positionals.push(a);
1712	    }
1713	  }
1714	  return {values, positionals};
1715	}
1716	
1717	function requireFlag(values: Map<string, string[]>, key: string): string {
1718	  const v = values.get(key)?.[0];
1719	  if (v === undefined) throw new UsageError(`缺少必需选项 --${key}`);
1720	  return v;
1721	}
