1891	// 清单结构（与数据文件无关的纯类型校验）；返回逐项原始记录
1892	function parseManifestShape(raw: unknown, file: string): Array<Record<string, unknown>> {
1893	  if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) {
1894	    throw new BizError(`改期清单 ${file} 内容非法：顶层必须是对象，形如 {"items": [...]}`);
1895	  }
1896	  const o = raw as Record<string, unknown>;
1897	  for (const k of Object.keys(o)) {
1898	    if (k !== 'items') throw new BizError(`改期清单 ${file} 内容非法：存在未知字段 “${k}”，只允许 items`);
1899	  }
1900	  if (!Array.isArray(o.items)) {
1901	    throw new BizError(`改期清单 ${file} 内容非法：items 必须是非空数组`);
1902	  }
1903	  const items = o.items as unknown[];
1904	  if (items.length === 0) throw new BizError(`改期清单 ${file} 为空：items 至少包含一项改期安排`);
1905	
1906	  const problems: string[] = [];
1907	  const records: Array<Record<string, unknown> | null> = [];
1908	  items.forEach((it, idx) => {
1909	    const at = `第 ${idx + 1} 项`;
1910	    if (typeof it !== 'object' || it === null || Array.isArray(it)) {
1911	      problems.push(`${at} 必须是对象`);
1912	      records.push(null);
1913	      return;
1914	    }
1915	    const rec = it as Record<string, unknown>;
1916	    for (const k of Object.keys(rec)) {
1917	      if (k !== 'bookingId' && k !== 'start' && k !== 'end' && k !== 'resourceIds') {
1918	        problems.push(`${at} 存在未知字段 “${k}”（只允许 bookingId、start、end、resourceIds）`);
1919	      }
1920	    }
1921	    if (typeof rec.bookingId !== 'string' || rec.bookingId === '') {
1922	      problems.push(`${at} 的 bookingId 必须是非空字符串`);
1923	    }
1924	    if (typeof rec.start !== 'string' || rec.start === '') {
1925	      problems.push(`${at} 的 start 必须是 YYYY-MM-DDTHH:mm 形式的非空字符串`);
1926	    }
1927	    if (typeof rec.end !== 'string' || rec.end === '') {
1928	      problems.push(`${at} 的 end 必须是 YYYY-MM-DDTHH:mm 形式的非空字符串`);
1929	    }
1930	    if (!Array.isArray(rec.resourceIds)) {
1931	      problems.push(`${at} 的 resourceIds 必须是非空数组（完整目标资源集合，整体替换原集合）`);
1932	    } else {
1933	      if (rec.resourceIds.length === 0) problems.push(`${at} 的 resourceIds 不能为空：资源集合整体替换，至少一个资源`);
1934	      rec.resourceIds.forEach((rid, j) => {
1935	        if (typeof rid !== 'string' || rid === '') {
1936	          problems.push(`${at}.resourceIds[${j}] 必须是非空资源标识字符串`);
1937	        }
1938	      });
1939	    }
1940	    records.push(rec);
1941	  });
1942	  if (problems.length > 0) {
1943	    throw new BizError(`改期清单 ${file} 内容非法，整批拒绝：\n${problems.map((p) => `- ${p}`).join('\n')}`);
1944	  }
1945	  return records as Array<Record<string, unknown>>;
1946	}
