3841	  }
3842	  const o = raw as Record<string, unknown>;
3843	  for (const k of Object.keys(o)) {
3844	    if (k !== 'items') throw new BizError(`改期清单 ${file} 内容非法：存在未知字段 “${k}”，只允许 items`);
3845	  }
3846	  if (!Array.isArray(o.items)) {
3847	    throw new BizError(`改期清单 ${file} 内容非法：items 必须是非空数组`);
3848	  }
3849	  const items = o.items as unknown[];
3850	  if (items.length === 0) throw new BizError(`改期清单 ${file} 为空：items 至少包含一项改期请求`);
3851	
3852	  const problems: string[] = [];
3853	  const records: Array<Record<string, unknown> | null> = [];
3854	  items.forEach((it, idx) => {
3855	    const at = `第 ${idx + 1} 项`;
3856	    if (typeof it !== 'object' || it === null || Array.isArray(it)) {
3857	      problems.push(`${at} 必须是对象`);
3858	      records.push(null);
3859	      return;
3860	    }
3861	    const rec = it as Record<string, unknown>;
3862	    for (const k of Object.keys(rec)) {
3863	      if (k !== 'bookingId' && k !== 'window' && k !== 'groups') {
3864	        problems.push(`${at} 存在未知字段 “${k}”（只允许 bookingId、window、groups）`);
3865	      }
3866	    }
3867	    if (typeof rec.bookingId !== 'string' || rec.bookingId === '') {
3868	      problems.push(`${at} 的 bookingId 必须是非空字符串`);
3869	    }
3870	    if (typeof rec.window !== 'string' || rec.window === '') {
3871	      problems.push(`${at} 的 window 必须是 窗口开始/窗口结束 形式的非空字符串`);
3872	    }
3873	    if (!Array.isArray(rec.groups) || rec.groups.length === 0) {
3874	      problems.push(`${at} 的 groups 必须是非空数组（至少一个有顺序的候选资源组）`);
3875	    } else {
3876	      rec.groups.forEach((g, gi) => {
3877	        if (!Array.isArray(g) || g.length === 0) {
3878	          problems.push(`${at} 第 ${gi + 1} 候选资源组必须是非空数组（可任选其一的候选资源标识）`);
3879	        } else {
3880	          g.forEach((id) => {
3881	            if (typeof id !== 'string' || id === '') {
3882	              problems.push(`${at} 第 ${gi + 1} 候选资源组含非法候选：候选资源标识必须是非空字符串`);
3883	            }
3884	          });
3885	        }
3886	      });
3887	    }
3888	    records.push(rec);
3889	  });
3890	  if (problems.length > 0) {
3891	    throw new BizError(`改期清单 ${file} 内容非法，整单拒绝：\n${problems.map((p) => `- ${p}`).join('\n')}`);
3892	  }
3893	  return records as Array<Record<string, unknown>>;
