3898	function parseFlexRescheduleItems(
3899	  store: Store,
3900	  records: Array<Record<string, unknown>>,
3901	  file: string,
3902	): FlexRescheduleItem[] {
3903	  const problems: string[] = [];
3904	  const seenBooking = new Map<string, number>(); // 标识 -> 首次出现的序号（1 基）
3905	  const items: Array<FlexRescheduleItem | null> = records.map((rec, idx) => {
3906	    const bookingId = rec.bookingId as string;
3907	    const at = `第 ${idx + 1} 项（${bookingId}）`;
3908	    let ok = true;
3909	
3910	    const firstAt = seenBooking.get(bookingId);
3911	    if (firstAt !== undefined) {
3912	      problems.push(`${at} 预约标识重复：该标识已在第 ${firstAt} 项出现，每项预约在清单中只能出现一次`);
3913	      ok = false;
3914	    } else {
3915	      seenBooking.set(bookingId, idx + 1);
3916	    }
3917	
3918	    const booking = store.bookings.find((b) => b.id === bookingId);
3919	    if (!booking) {
3920	      problems.push(`${at} 未知预约标识: ${bookingId}`);
3921	      ok = false;
3922	    } else if (booking.status === 'cancelled') {
3923	      problems.push(`${at} 预约 ${booking.id} 已取消，不能改期`);
3924	      ok = false;
3925	    }
3926	
3927	    let win: {start: string; end: string; startMin: number; endMin: number} | null = null;
3928	    try {
3929	      win = parseFlexWindow(rec.window as string, `${at}窗口`);
3930	    } catch (err) {
3931	      if (err instanceof BizError) {
3932	        problems.push(err.message);
3933	        ok = false;
3934	      } else {
3935	        throw err;
3936	      }
3937	    }
3938	
3939	    let duration = 0;
3940	    let curStartMin = 0;
3941	    if (booking !== undefined) {
3942	      curStartMin = parseDateTime(booking.start, `${at} 当前开始时间`);
3943	      duration = parseDateTime(booking.end, `${at} 当前结束时间`) - curStartMin;
3944	    }
3945	    if (win !== null && booking !== undefined && win.endMin - win.startMin < duration) {
3946	      problems.push(
3947	        `${at} 窗口长度 ${win.endMin - win.startMin} 分钟小于预约当前时长 ${duration} 分钟` +
3948	          `（窗口: ${win.start} → ${win.end}，时长保持预约当前长度）`,
3949	      );
3950	      ok = false;
3951	    }
3952	
3953	    const groups: RequirementGroup[] = [];
3954	    (rec.groups as string[][]).forEach((ids, gi) => {
3955	      const glabel = `${at} 第 ${gi + 1} 候选资源组`;
3956	      const seen = new Set<string>();
3957	      const dupes: string[] = [];
3958	      for (const id of ids) {
3959	        if (seen.has(id) && !dupes.includes(id)) dupes.push(id);
3960	        seen.add(id);
3961	      }
3962	      if (dupes.length > 0) {
3963	        problems.push(`${glabel}内候选资源重复: ${dupes.join('、')}`);
3964	        ok = false;
3965	      }
3966	      const unknown = [...seen].filter((id) => !store.resources.some((r) => r.id === id)).sort();
3967	      if (unknown.length > 0) {
3968	        problems.push(`${glabel}含未知资源标识: ${unknown.join('、')}`);
3969	        ok = false;
3970	      }
3971	      groups.push({index: gi + 1, candidates: [...seen].sort()});
3972	    });
3973	
3974	    if (!ok || win === null || booking === undefined) return null;
3975	    return {
3976	      index: idx + 1,
3977	      booking,
3978	      startRaw: win.start,
3979	      endRaw: win.end,
3980	      startMin: win.startMin,
3981	      endMin: win.endMin,
3982	      duration,
3983	      curStartMin,
3984	      curResourceIds: [...booking.resourceIds].sort(),
3985	      groups,
3986	    };
3987	  });
3988	  if (problems.length > 0) {
3989	    throw new BizError(`改期清单 ${file} 校验失败，整单拒绝（原有安排保持不变）：\n${problems.map((p) => `- ${p}`).join('\n')}`);
3990	  }
3991	  return items as FlexRescheduleItem[];
3992	}
