3994	// 所选资源序列（按组顺序）与当前资源集合是否一致（资源顺序不计）
3995	function sameResourceSet(picks: string[], curSorted: string[]): boolean {
3996	  if (picks.length !== curSorted.length) return false;
3997	  const sorted = [...picks].sort();
3998	  return sorted.every((id, i) => id === curSorted[i]);
