4001	// 联合求解整单最终安排：先最小化变化预约数量，数量相同再按清单顺序逐项
4002	// 先比开始分钟、再按组序比资源标识字符串，取字典序最小完整方案。
4003	// 返回按清单顺序的各项安排（开始分钟 + 各组所选资源），无整体解返回 null。
4004	function solveFlexReschedule(store: Store, items: FlexRescheduleItem[]): FlexPlacement[] | null {
4005	  // 本批预约的旧占用一律不视为障碍；其余有效预约按现状阻挡
4006	  const batchIds = new Set(items.map((it) => it.booking.id));
4007	  const baseFree: Array<Map<string, Array<[number, number]>>> = items.map((it) => {
4008	    const m = new Map<string, Array<[number, number]>>();
4009	    for (const g of it.groups) {
4010	      for (const id of g.candidates) {
4011	        if (!m.has(id)) m.set(id, resourceFreeSegments(store, id, it.startMin, it.endMin, batchIds));
4012	      }
4013	    }
4014	    return m;
4015	  });
4016	
4017	  // 候选开始分钟闭包：基础空闲段起点 ∪ 各项当前开始（在窗内时），
4018	  // 加上“被其他项占用结束顶住”的起点 s_i = s_j + d_j
4019	  // （仅候选资源集合有交集的项之间传播；值域有限，必收敛）
4020	  const candidateIds = items.map((it) => {
4021	    const set = new Set<string>();
4022	    for (const g of it.groups) for (const id of g.candidates) set.add(id);
4023	    return set;
4024	  });
4025	  const sharesCandidate = (a: number, b: number): boolean => {
4026	    for (const id of candidateIds[a]) if (candidateIds[b].has(id)) return true;
4027	    return false;
4028	  };
4029	  const candStarts: Array<Set<number>> = items.map((it, i) => {
4030	    const set = new Set<number>();
4031	    for (const segs of baseFree[i].values()) {
4032	      for (const [s] of segs) {
4033	        if (s + it.duration <= it.endMin) set.add(s);
4034	      }
4035	    }
4036	    // 当前开始落在窗内时，“保持现状”总是一个候选（是否可行在试探中判定）
4037	    if (it.curStartMin >= it.startMin && it.curStartMin + it.duration <= it.endMin) {
4038	      set.add(it.curStartMin);
4039	    }
4040	    return set;
4041	  });
4042	  let changed = true;
4043	  while (changed) {
4044	    changed = false;
4045	    for (let j = 0; j < items.length; j++) {
4046	      for (let i = 0; i < items.length; i++) {
4047	        if (i === j || !sharesCandidate(i, j)) continue;
4048	        for (const s of candStarts[j]) {
4049	          const t = s + items[j].duration;
4050	          if (
4051	            t >= items[i].startMin &&
4052	            t + items[i].duration <= items[i].endMin &&
4053	            !candStarts[i].has(t)
4054	          ) {
4055	            candStarts[i].add(t);
4056	            changed = true;
4057	          }
4058	        }
4059	      }
4060	    }
4061	  }
4062	
4063	  // 已放置项对各资源的占用（随试探入栈/出栈增减；不变项同样放置以阻挡他项）
4064	  const occById = new Map<string, Array<[number, number]>>();
4065	
4066	  // 按清单顺序深度优先：开始分钟升序、同一开始的资源序列字典序升序，
4067	  // 只接受变化数不超过 budget 的完整方案；首个完整方案即该预算下的最小方案
4068	  const search = (idx: number, budget: number): FlexPlacement[] | null => {
4069	    if (idx === items.length) return [];
4070	    const it = items[idx];
4071	    const freeById = new Map<string, Array<[number, number]>>();
4072	    for (const [id, segs] of baseFree[idx]) {
4073	      const occ = occById.get(id);
4074	      freeById.set(id, occ !== undefined && occ.length > 0 ? subtractSegments(segs, occ) : segs);
4075	    }
4076	    for (const s of [...candStarts[idx]].sort((a, b) => a - b)) {
4077	      const e = s + it.duration;
4078	      const cache = new Map<string, boolean>();
4079	      const usable = (id: string): boolean => {
4080	        let v = cache.get(id);
4081	        if (v === undefined) {
4082	          v = isFullyCovered(freeById.get(id)!, s, e);
4083	          cache.set(id, v);
4084	        }
4085	        return v;
4086	      };
4087	      for (const picks of assignmentsInLexOrder(it.groups, usable)) {
4088	        // 起止时间或完整资源集合任一不同才算变化（时长固定，开始即决定结束；资源顺序不计）
4089	        const cost = s === it.curStartMin && sameResourceSet(picks, it.curResourceIds) ? 0 : 1;
4090	        if (cost > budget) continue;
4091	        for (const id of picks) {
4092	          const occ = occById.get(id) ?? [];
4093	          occ.push([s, e]);
4094	          occById.set(id, occ);
4095	        }
4096	        const rest = search(idx + 1, budget - cost);
4097	        if (rest !== null) return [{startMin: s, endMin: e, picks}, ...rest];
4098	        for (const id of picks) occById.get(id)!.pop();
4099	      }
4100	    }
4101	    return null;
4102	  };
4103	
4104	  // 变化数 k 递增：首个有解的 k 即最少变化数，其首个完整方案即最终取舍
4105	  for (let k = 0; k <= items.length; k++) {
4106	    const plan = search(0, k);
4107	    if (plan !== null) return plan;
4108	  }
4109	  return null;
4110	}
