122	// 断言弹性批量改期输出：按清单顺序的各项预约标识、起止时间与按组对应的资源
123	function assertPlan(r: CliResult, opId: string, expected: ExpectedItem[], ctx: string): void {
124	  assert.match(
125	    r.stdout,
126	    new RegExp(`弹性批量改期成功：操作标识 ${opId}，共 ${expected.length} 项`),
