662	    ['reschedule-flex', writeRaw('n14.json', '{"items": [{"bookingId": "B0009", "window": "2026-10-12T10:00/2026-10-12T12:00", "groups": [["R0001"]]}]}')],
663	    '未知预约',
664	  );
