666	  r = bizFail(
667	    df,
668	    ['reschedule-flex', writeRaw('n15.json', '{"items": [{"bookingId": "B0001", "window": "2026-10-12T10:00/2026-10-12T12:00", "groups": [["R0001"]]}, {"bookingId": "B0001", "window": "2026-10-12T10:00/2026-10-12T12:00", "groups": [["R0001"]]}]}')],
669	    '重复预约',
