672	  r = bizFail(
673	    df,
674	    ['reschedule-flex', writeRaw('n16.json', '{"items": [{"bookingId": "B0002", "window": "2026-10-12T10:00/2026-10-12T12:00", "groups": [["R0001"]]}]}')],
675	    '已取消预约',
676	  );
677	  assert.match(r.stderr, /预约 B0002 已取消，不能改期/);
678	
679	  assertFileBytes(df, bytesBefore, '全部失败请求后');
680	  const store = readStore(df);
681	  assert.equal(store.batchOps.length, 0, '失败请求不产生记录');
682	  assert.equal(store.batchSeq, 0, '失败请求不消耗操作计数');
683	});
684	
685	// ---------------------------------------------------------------------------
686	// 10. 损坏数据文件退出 1 并保留原样；旧格式文件可直接弹性批量改期
687	// ---------------------------------------------------------------------------
688	
689	test('损坏数据文件退出 1 并保留原样；旧格式文件可直接弹性批量改期', (t) => {
690	  const dir = tempDir(t);
691	
692	  // 旧格式文件（只有 version 与 resources 及一条预约，无后续版本字段）
