696	    JSON.stringify({
697	      version: 1,
698	      resources: [{id: 'R0001', type: 'venue', name: '旧会议室', open: [['2026-01-01T00:00', '2027-01-01T00:00']]}],
699	      bookings: [{id: 'B0001', resourceIds: ['R0001'], start: '2026-10-12T09:00', end: '2026-10-12T10:00', status: 'active'}],
700	      bookingSeq: 1,
