708	  const r = rescheduleFlex(old, manifest, '旧文件弹性批量改期');
709	  assertPlan(r, 'O0001', [{id: 'B0001', start: '2026-10-12T14:00', end: '2026-10-12T15:00', picks: ['R0001']}], '旧文件改期');
710	  assertBooking(old, 'B0001', '2026-10-12T14:00', '2026-10-12T15:00', ['R0001'], '旧文件落盘');
711	
