  addBooking(df, ['R0001'], '2026-10-12T10:00', '2026-10-12T11:00', 'B0001 必纳');
  addBooking(df, ['R0001'], '2026-10-12T11:00', '2026-10-12T12:00', 'B0002 必纳');
  addBooking(df, ['R0001', 'R0003'], '2026-10-12T10:30', '2026-10-12T11:30', 'B0003 多资源必纳');
